cz →","to":"/investments/pod-stokiem-willa/docs/standard-wykonczenia.pdf","target":"_blank"}}}],"editable":true,"label":"Pliki do pobrania"}}},{"id":"separator-4","component":"Separator","type":"section","label":"Odstęp","fields":{}},{"id":"section-header-wizualizacje","component":"SectionHeader","type":"section","label":"Wizualizacje","fields":{"header":{"value":"Wizualiazacje – Willa Pod Stokiem","editable":true,"label":"Nagłówek"},"subHeader":{"value":"Zobacz, jak będzie wyglądać Willa Pod Stokiem. Wizualizacje prezentują architekturę budynku, przestronne wnętrza oraz strefy relaksu, oddając charakter inwestycji i standard wykończenia. To zapowiedź stylu życia, który oferuje ta wyjątkowa willa w Krakowie.","editable":true,"label":"Opis"}}},{"id":"gallery","component":"Gallery","type":"section","label":"Galeria","fields":{"gallery":{"value":[{"url":"/investments/pod-stokiem-willa/willa-podstokiem5.png"},{"url":"/investments/pod-stokiem-willa/willa-podstokiem3.webp"},{"url":"/investments/pod-stokiem-willa/willa-podstokiem4.png"},{"url":"/investments/pod-stokiem-willa/willa-podstokiem2.png"}],"editable":true,"label":"Zdjęcia galerii"}}},{"id":"separator-5","component":"Separator","type":"section","label":"Odstęp","fields":{"custom":{"style":["bg-[#F6F6F6]"]}}},{"id":"big-image-3","component":"BigImageSection","type":"section","label":"Umów prezentację","fields":{"image":{"url":"/investments/pod-stokiem-willa/willa-podstokiem2.png"},"header":{"value":"Umów się na prezentację Willi Pod Stokiem","editable":true,"label":"Nagłówek"},"subHeader":{"value":"Odkryj osobiście komfort i prestiż tej wyjątkowej inwestycji. Skontaktuj się z nami, aby umówić indywidualną prezentację i przekonać się, jak Willa Pod Stokiem może stać się Twoim nowym domem.","editable":true,"label":"Podtytuł"}}},{"id":"deweloper","component":"Deweloper","type":"section","label":"KGD - Deweloper","fields":{"header":{"value":"KGD - Deweloper","editable":true,"label":"Nagłówek"},"aboutKGD":{"value":"WOLA JUSTOWSKA INWESTYCJE SP Z O.O. stanowi część Krakowskiej Grupy Deweloperskiej (KGD) to wiodący deweloper specjalizujący się w realizacji inwestycji premium w najbardziej prestiżowych lokalizacjach Krakowa. Portfolio KGD to szereg zrealizowanych z sukcesem projektów, które wyróżniają się najwyższą jakością wykonania i bezkompromisowym podejściem do detali. Każda nasza inwestycja to starannie przemyślana koncepcja, łącząca kameralny charakter z ponadczasową elegancją. Obecnie, bazując na naszym doświadczeniu, planujemy rozwój działalności w kolejnych dzielnicach Krakowa.","editable":true,"label":"Opis"},"buttonLabel":{"value":"Dowiedz się więcej","editable":true,"label":"Etykieta przycisku"}}},{"id":"contact","component":"Contact","type":"section","label":"Kontakt","fields":{"heading":{"value":"Kontakt","editable":true,"label":"Nagłówek"},"label":{"value":"Masz pytania o nasze inwestycje lub chcesz dowiedzieć się więcej o WOLA JUSTOWSKA INWESTYCJE SPÓŁKA Z OGRANICZONĄ ODPOWIEDZIALZIALNOŚCIĄ? Wypełnij formularz, a skontaktujemy się z Tobą.","editable":true,"label":"Opis"},"company":{"value":"WOLA JUSTOWSKA INWESTYCJE SP. Z O.O.","editable":true,"label":"Nazwa firmy"},"address":{"value":"ul. Koło Strzelnicy 2 / 2, 30-219 Kraków","editable":true,"label":"Adres"},"phone":{"value":"12 352 15 00","editable":true,"label":"Telefon"},"email":{"value":"sprzedaz@willa-podstokiem.pl","editable":true,"label":"Email"},"nip":{"value":"6772520487","editable":true,"label":"NIP"},"krs":{"value":"0001148769","editable":true,"label":"KRS"},"regon":{"value":"540629760","editable":true,"label":"REGON"},"fieldLabels":{"value":{"company":"Firma","address":"Adres","phone":"Telefon","email":"Email","krs":"KRS","nip":"NIP","regon":"REGON"},"editable":true,"label":"Etykiety pól"},"placeholders":{"value":{"name":"Imię i nazwisko *","email":"Email *","subject":"Temat *","message":"Wiadomość *"},"editable":true,"label":"Placeholdery formularza"},"consents":{"value":{"consent":{"label":"* Wyrażam z